// Đọc tin Zalo gửi tới, kiểm tra mã bí mật, rồi quyết định bước tiếp theo.
const cfg = $('Cấu hình').first().json;
const req = $input.first().json;
const headers = req.headers || {};

// Chỉ nhận tin do chính Zalo gửi (đúng mã bí mật đã đăng ký)
if (String(headers['x-bot-api-secret-token'] || '') !== String(cfg.MA_BI_MAT)) {
  return [];
}

const body = req.body || {};
const update = body.result || body;
const msg = update.message || {};
const chatId = String((msg.chat && msg.chat.id) || (msg.from && msg.from.id) || '');
const sender = (msg.from && (msg.from.display_name || msg.from.name)) || '';
const text = String(msg.text || '').trim();
if (!chatId) return [];

const HELP =
  'Chào bạn, mình là ZaloPlan 👋\n\n' +
  'Chuyển tiếp (forward) hoặc dán tin nhắn giao việc cho mình, mình sẽ tự lưu thành công việc.\n\n' +
  'Các lệnh:\n' +
  '• viec: xem việc đang mở\n' +
  '• xong ABCD: đánh dấu việc ABCD đã xong\n' +
  '• xoa ABCD: xóa việc ABCD (khi AI hiểu sai)';

const out = (o) => [{ json: { chatId, sender, text, ...o } }];

if (update.event_name && update.event_name !== 'message.text.received') {
  return out({ route: 'tra_loi', reply: 'Hiện mình chỉ đọc được tin nhắn chữ. Bạn dán nội dung tin nhắn giúp mình nhé.' });
}
if (!text) return [];

// Bỏ dấu tiếng Việt để nhận lệnh dù gõ có dấu hay không
const plain = text
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .toLowerCase().replace(/\s+/g, ' ').trim();

let m = plain.match(/^\/?(xong|done|ok xong)\s+#?([a-z0-9]{4})$/);
if (m) return out({ route: 'sheet', lenh: 'cap_nhat', trangThai: 'Xong', taskId: m[2].toUpperCase() });
m = plain.match(/^\/?(xoa|huy)\s+#?([a-z0-9]{4})$/);
if (m) return out({ route: 'sheet', lenh: 'cap_nhat', trangThai: 'Đã xóa', taskId: m[2].toUpperCase() });
if (/^\/?(viec|ds|danh sach|list|cong viec)$/.test(plain)) return out({ route: 'sheet', lenh: 'danh_sach' });
if (/^\/?(start|help|huong dan|hd|menu)$/.test(plain)) return out({ route: 'tra_loi', reply: HELP });
if (plain.length < 4) {
  return out({ route: 'tra_loi', reply: 'Mình chưa thấy việc nào trong tin này. Gõ "hd" để xem hướng dẫn.' });
}

// ---- Chuẩn bị câu hỏi cho AI ----
const TZ = 'Asia/Ho_Chi_Minh';
const THU = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];
const nowMs = Date.now();
const vn = (ms) => {
  const d = new Date(ms + 7 * 3600 * 1000); // giờ Việt Nam (UTC+7, không đổi giờ)
  const p = (n) => String(n).padStart(2, '0');
  return {
    ymd: `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`,
    dm: `${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`,
    hm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`,
    thu: THU[d.getUTCDay()],
  };
};
const now = vn(nowMs);
const lich = [];
for (let i = 0; i <= 14; i++) {
  const d = vn(nowMs + i * 86400000);
  lich.push(`${d.thu} ${d.dm} = ${d.ymd}${i === 0 ? ' (hôm nay)' : i === 1 ? ' (ngày mai)' : ''}`);
}

const system = [
  'Bạn là trợ lý đọc tin nhắn Zalo tiếng Việt và tách ra các công việc cần làm.',
  'Quy tắc:',
  '- Chỉ tạo việc khi tin nhắn có yêu cầu, nhiệm vụ hoặc lời hẹn cần làm. Chào hỏi, cảm ơn, xác nhận ("ok", "đã nhận"), chuyện phiếm thì trả về danh sách rỗng.',
  '- Một tin có thể có nhiều việc; tách riêng từng việc.',
  '- viec: ngắn gọn, bắt đầu bằng động từ, tối đa 80 ký tự, giữ tên riêng và con số quan trọng.',
  '- nguoi_lam: tên người được giao (ví dụ "Lan ơi..." thì là Lan). Không rõ thì để chuỗi rỗng.',
  '- han_chot: dạng "YYYY-MM-DD HH:mm" theo giờ Việt Nam, tính từ thời điểm hiện tại và lịch được cho. Quy ước giờ: sáng 09:00, trưa 12:00, chiều 17:00, tối 20:00, cuối ngày 17:00; chỉ có ngày mà không có giờ thì 17:00. "Thứ X" là thứ X gần nhất sắp tới; "thứ X tuần sau" là thứ X của tuần kế tiếp; "cuối tuần" là Thứ Bảy; "cuối tháng" là ngày cuối tháng. Không có hạn thì để chuỗi rỗng, không tự đoán.',
  '- uu_tien: "Cao" nếu có gấp, khẩn, ASAP, quan trọng, ngay; "Thấp" nếu khi rảnh, không gấp; còn lại "Bình thường".',
  '- du_an: tên dự án, công trình, khách hàng hoặc đơn hàng nếu có, không thì chuỗi rỗng.',
  '- Hiểu cả tiếng Việt không dấu và viết tắt: ko/k = không, dc/đc = được, a = anh, e = em, c = chị, nhé/nha/nhe.',
].join('\n');

const userMsg = [
  `Thời điểm hiện tại: ${now.thu}, ${now.dm} ${now.hm} (giờ Việt Nam).`,
  'Lịch tham khảo:',
  ...lich,
  '',
  `Người gửi tin cho bot: ${sender || '(không rõ)'}`,
  'Tin nhắn:',
  '"""',
  text.slice(0, 4000),
  '"""',
].join('\n');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['tasks'],
  properties: {
    tasks: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['viec', 'nguoi_lam', 'han_chot', 'uu_tien', 'du_an'],
        properties: {
          viec: { type: 'string' },
          nguoi_lam: { type: 'string' },
          han_chot: { type: 'string' },
          uu_tien: { type: 'string', enum: ['Cao', 'Bình thường', 'Thấp'] },
          du_an: { type: 'string' },
        },
      },
    },
  },
};

const aiRequest = {
  model: cfg.MO_HINH_AI,
  max_tokens: 4000,
  fallbacks: 'default',
  output_config: { effort: 'low', format: { type: 'json_schema', schema } },
  system,
  messages: [{ role: 'user', content: userMsg }],
};

return out({ route: 'ai', aiRequest, nowText: `${now.ymd} ${now.hm}` });

// Đọc kết quả AI, tạo các dòng công việc để lưu vào Google Sheet và soạn tin trả lời.
const tin = $('Đọc tin Zalo').first().json;
const res = $input.first().json || {};
const THU = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];

const traLoi = (reply) => [{ json: { chatId: tin.chatId, reply, coViec: false, rows: [] } }];

if (res.type === 'error' || res.error) {
  const loi = (res.error && (res.error.message || res.error.type)) || 'không rõ';
  return traLoi(`⚠️ AI đang gặp lỗi nên chưa lưu được việc.\nChi tiết: ${String(loi).slice(0, 300)}\nBạn kiểm tra lại khóa AI (API key) và số dư tài khoản AI nhé.`);
}
if (res.stop_reason === 'refusal') {
  return traLoi('⚠️ AI không xử lý tin nhắn này. Bạn thử viết lại ngắn gọn hơn nhé.');
}

const block = (res.content || []).filter((b) => b.type === 'text').pop();
let tasks = [];
try {
  tasks = JSON.parse(block ? block.text : '{}').tasks || [];
} catch (e) {
  return traLoi('⚠️ Mình đọc kết quả AI bị lỗi. Bạn gửi lại tin nhắn giúp mình nhé.');
}

const isDate = (s) => /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(s) && !isNaN(Date.parse(s.replace(' ', 'T') + ':00+07:00'));
const hienHan = (s) => {
  if (!s) return 'chưa có hạn';
  const d = new Date(Date.parse(s.replace(' ', 'T') + ':00+07:00') + 7 * 3600 * 1000);
  return `${s.slice(11)} ${THU[d.getUTCDay()]} ${s.slice(8, 10)}/${s.slice(5, 7)}`;
};
const ABC = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const taoId = () => Array.from({ length: 4 }, () => ABC[Math.floor(Math.random() * ABC.length)]).join('');

const rows = tasks
  .filter((t) => t && String(t.viec || '').trim())
  .slice(0, 10)
  .map((t) => ({
    ID: taoId(),
    Viec: String(t.viec).trim().slice(0, 200),
    NguoiLam: String(t.nguoi_lam || '').trim(),
    HanChot: isDate(String(t.han_chot || '')) ? t.han_chot : '',
    UuTien: ['Cao', 'Bình thường', 'Thấp'].includes(t.uu_tien) ? t.uu_tien : 'Bình thường',
    DuAn: String(t.du_an || '').trim(),
    TrangThai: 'Mới',
    TinGoc: tin.text.slice(0, 1000),
    NguoiGui: tin.sender,
    ChatID: tin.chatId,
    TaoLuc: tin.nowText,
    XongLuc: '',
    DaNhac: '',
  }));

if (!rows.length) {
  return traLoi('Mình không thấy việc nào cần làm trong tin này. Nếu có, bạn viết rõ hơn (ai làm, việc gì, hạn khi nào) nhé.');
}

const dong = rows.map((r) => {
  const chiTiet = [r.NguoiLam && `👤 ${r.NguoiLam}`, `⏰ ${hienHan(r.HanChot)}`, r.UuTien === 'Cao' && '🔥 Gấp', r.DuAn && `📁 ${r.DuAn}`]
    .filter(Boolean).join(' · ');
  return `[${r.ID}] ${r.Viec}\n${chiTiet}`;
});
const reply =
  `📝 Đã lưu ${rows.length} việc:\n\n${dong.join('\n\n')}\n\n` +
  `Làm xong thì trả lời "xong ${rows[0].ID}". AI hiểu sai thì "xoa ${rows[0].ID}".`;

return [{ json: { chatId: tin.chatId, reply: reply.slice(0, 2000), coViec: true, rows } }];

// Xử lý lệnh "viec", "xong ABCD", "xoa ABCD" dựa trên các việc của người này trong Google Sheet.
const tin = $('Đọc tin Zalo').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.ID);
const THU = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];

// Đọc hạn chót: nhận "2026-10-16 17:00" hoặc "16/10/2026 17:00" (khi sửa tay trong Sheet)
const hanMs = (s) => {
  s = String(s || '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2}))?/);
  if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3], m[4] ? +m[4] : 17, m[5] ? +m[5] : 0) - 7 * 3600 * 1000;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?/);
  if (m) return Date.UTC(+m[3], +m[2] - 1, +m[1], m[4] ? +m[4] : 17, m[5] ? +m[5] : 0) - 7 * 3600 * 1000;
  return null;
};
const p = (n) => String(n).padStart(2, '0');
const vn = (ms) => {
  const d = new Date(ms + 7 * 3600 * 1000);
  return { ymd: `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`, hm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`, thu: THU[d.getUTCDay()], dm: `${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}` };
};
const now = Date.now();

if (tin.lenh === 'cap_nhat') {
  const viec = rows.find((r) => String(r.ID).toUpperCase() === tin.taskId);
  if (!viec) {
    return [{ json: { canCapNhat: false, chatId: tin.chatId, reply: `Mình không tìm thấy việc ${tin.taskId} của bạn. Gõ "viec" để xem mã các việc đang mở.` } }];
  }
  const t = vn(now);
  const reply = tin.trangThai === 'Xong'
    ? `✅ Tuyệt! Đã đánh dấu xong: [${viec.ID}] ${viec.Viec}`
    : `🗑 Đã xóa việc: [${viec.ID}] ${viec.Viec}`;
  return [{ json: { canCapNhat: true, chatId: tin.chatId, reply, ID: viec.ID, TrangThai: tin.trangThai, XongLuc: `${t.ymd} ${t.hm}` } }];
}

// Lệnh "viec": liệt kê việc đang mở, sắp theo hạn
const mo = rows
  .filter((r) => r.TrangThai === 'Mới')
  .map((r) => ({ ...r, _han: hanMs(r.HanChot) }))
  .sort((a, b) => (a._han ?? Infinity) - (b._han ?? Infinity));

if (!mo.length) {
  return [{ json: { canCapNhat: false, chatId: tin.chatId, reply: '🎉 Bạn không còn việc nào đang mở. Chuyển tiếp tin giao việc cho mình để thêm việc mới nhé.' } }];
}
const homNay = vn(now).ymd;
const dong = mo.slice(0, 30).map((r) => {
  let han = 'chưa có hạn';
  if (r._han != null) {
    const d = vn(r._han);
    han = d.ymd === homNay ? `hôm nay ${d.hm}` : `${d.hm} ${d.thu} ${d.dm}`;
    if (r._han < now) han = `⚠️ trễ hạn (${d.dm})`;
  }
  return `• [${r.ID}] ${r.Viec}${r.NguoiLam ? ` (${r.NguoiLam})` : ''}: ${han}${r.UuTien === 'Cao' ? ' 🔥' : ''}`;
});
const them = mo.length > 30 ? `\n…và ${mo.length - 30} việc khác.` : '';
const reply = `📋 Bạn có ${mo.length} việc đang mở:\n\n${dong.join('\n')}${them}\n\nLàm xong thì trả lời "xong" kèm mã việc.`;
return [{ json: { canCapNhat: false, chatId: tin.chatId, reply: reply.slice(0, 2000) } }];
